import { Implementation } from './Implementation';

export class Webassembly {
    implementation: Implementation;
    host: HTMLElement;
    divText: HTMLElement;

    constructor(id: string = 'main') {
        const host = document.getElementById(id);
        if (host) {
            this.host = host;
        }
        const divText = document.createElement('div');
        if (divText) {
            this.divText = divText;
            this.host.append(this.divText);
        }
        this.implementation = new Implementation(this);
    }
    public destroy(){
        while(this.host.lastChild) {
            this.host.removeChild(this.host.lastChild);
        }
    }
}

export class Solution {
    divHost
    webassembly
    constructor(id: string) {
      this.divHost = document.getElementById(id) as HTMLDivElement;

      this.webassembly = new Webassembly(id)
    }
    public destroy() {
        this.webassembly.destroy()
        while (this.divHost.lastElementChild) {
            this.divHost.removeChild(this.divHost.lastElementChild);
        }
    }
  }